(n, m) = input().strip().split()
n = int(n)
m = int(m)
a = [[0] * (m + 1) for _ in range(n + 1)]
for i in range(n):
	s = input().strip()
	for j in range(m):
		if s[j] == 'B':
			a[i + 1][j + 1] = 1
		if i > 0:
			a[i][j + 1] ^= a[i + 1][j + 1]
		if j > 0:
			a[i + 1][j] ^= a[i + 1][j + 1]
		if i > 0 and j > 0:
			a[i][j] ^= a[i + 1][j + 1]
res = 0
sub = 0
for i in range(1, n + 1):
	for j in range(1, m + 1):
		if a[i][j] == 1:
			res += 1
		if i < n and j < m and a[i][j] and a[i][m] and a[n][j] and a[n][m]:
			sub = 1
print(res - sub)
